"""Install the immutable Nov26 FB allocation-only runtime (58 targets, 36 stopped)."""
import ast,base64,hashlib,json,os,subprocess,sys,zlib
from pathlib import Path
FINGERPRINT='5c5b057ba5fa9748d4aa78ae9f22e17b12b6ded462ae1fea2447abd8bd153bec'
ADDITIONS={n:base64.b64decode(b) for n,b in json.loads(zlib.decompress(base64.b64decode(''))).items()}

def safe(path):
    for item in (path,*path.parents):
        if (item.exists() or item.is_symlink()) and (item.is_symlink() or bool(getattr(item.lstat(),'st_file_attributes',0)&0x400)):raise ValueError('路径包含链接，未安装或分配素材')
    return path

def install(root):
    root=safe(Path(root).absolute()).resolve()
    if not safe(root/'upload_config.json').is_file() or not safe(root/'.venv/Scripts/python.exe').is_file():raise ValueError('原FB上传配置或Python缺失')
    manifest={n:hashlib.sha256(b).hexdigest() for n,b in ADDITIONS.items()}
    if hashlib.sha256(json.dumps(manifest,sort_keys=True).encode()).hexdigest()!=FINGERPRINT:raise ValueError('分配工具指纹异常')
    folder=safe(root/'material-staging/tools'/('nov26-allocate58-'+FINGERPRINT[:16]));folder.mkdir(parents=True,exist_ok=True)
    for n,b in dict(ADDITIONS,**{'runtime-sha256.json':json.dumps(manifest,sort_keys=True).encode()}).items():
        if Path(n).name!=n:raise ValueError('工具文件名异常')
        if n.endswith('.py'):ast.parse(b.decode('utf-8-sig'))
        path=safe(folder/n)
        if path.exists():
            if path.read_bytes()!=b:raise ValueError('不可变工具缓存已变化，未覆盖：'+n)
        else:
            with path.open('xb') as h:h.write(b);h.flush();os.fsync(h.fileno())
    for n,sha in manifest.items():
        if hashlib.sha256(safe(folder/n).read_bytes()).hexdigest()!=sha:raise ValueError('安装后指纹异常')
    return root,folder

VERIFY="import sys;from pathlib import Path;sys.path.insert(0,sys.argv[2]);sys.path.insert(0,sys.argv[1]);import distribute_eligible58_materials_20261126 as d;assert d.DAY=='2026-11-26' and len(d.EXPECTED)==58 and len(d.UNAVAILABLE)==36;assert {'fb32','fb52'}<=d.UNAVAILABLE;assert len({a for a,t in d.EXPECTED})==38;assert sum(t=='personal' for a,t in d.EXPECTED)==32;assert sum(t.startswith('page') for a,t in d.EXPECTED)==26;assert d.stage.upload.ROOT.resolve()==Path(sys.argv[2]).resolve();d.stage.setup(Path(sys.argv[2]));rows,_=d.stage.target_snapshot(Path(sys.argv[2]));assert len(rows)==58;print('VERIFIED: Nov26 FB allocation only; 38 accounts / 58 targets; skip36 including fb32/fb52; no publication or cleanup',flush=True)"

def start(root):
    if sys.platform!='win32':raise ValueError('请在原Windows上传电脑运行')
    root,folder=install(root)
    subprocess.run([sys.executable,'-c',VERIFY,str(folder),str(root)],cwd=root,check=True)
    print('请选择今天的FB总素材文件夹：至少58条未分配MP4；按自然顺序每目标1条，原件保留。Instagram目录保持原样。',flush=True)
    result=subprocess.run([sys.executable,'-u',str(folder/'distribute_eligible58_materials_20261126.py'),str(root)],cwd=root)
    if result.returncode not in {0,130}:raise RuntimeError('今天素材分配未完成，请查看上方原因；原件和已有进度保留')
    return result.returncode

if __name__=='__main__':
    sys.stdout.reconfigure(encoding='utf-8',line_buffering=True)
    try:raise SystemExit(start(Path(sys.argv[1])))
    except KeyboardInterrupt:print('已暂停分配，原素材和进度保留。',flush=True);raise SystemExit(130)
    except Exception as error:print('STOP：'+(str(error) or type(error).__name__),flush=True);raise SystemExit(1)
